EXPORT ZZT_POLY() BEGIN
RECT_P(#020406h);
LOCAL accepted:=1,result:=99,x,y,pixels:={};
IFERR result:=FILLPOLY_P([[1.8,0.8],[6.8,2.8],[3.8,6.8],[-1.8,3.8]],#FE8040h,128); THEN accepted:=0; END;
FOR y FROM 0 TO 6 DO FOR x FROM 0 TO 6 DO
 pixels:=CONCAT(pixels,{B→R(GETPIX_P(x,y))});
END;END;
RETURN {accepted,TYPE(result),STRING(result),pixels};
END;

EXPORT ZZT_CARTPOLY() BEGIN
Xmin:=-17.5; Xmax:=141.5; Ymin:=-394; Ymax:=42;
LOCAL x,y,r,ok,a;
RECT_P(#020406h); r:=-1; ok:=1; a:={};
IFERR r:=FILLPOLY({(-18.85,38.2),(-15.200,44.2),(-14.150,31.10),(-16.890,30.38)},#FF8048h,83); THEN ok:=0; END;
FOR y FROM 0 TO 6 DO FOR x FROM 0 TO 6 DO
 a:=CONCAT(a,{B→R(GETPIX_P(x,y))});
END; END;
RETURN {ok,r,a}; END;
